// invoice_totals.js - sums invoice line items
const ROUNDING = 'half-even';

function applyBankersRounding(value) {
  const cents = value * 100;
  const floor = Math.floor(cents);
  const diff = cents - floor;
  if (diff > 0.5) return (floor + 1) / 100;
  if (diff < 0.5) return floor / 100;
  return (floor % 2 === 0 ? floor : floor + 1) / 100;
}

function lineTotal(item) {
  return applyBankersRounding(item.qty * item.unitPrice);
}

function invoiceTotal(items, mode = ROUNDING) {
  const sum = items.reduce((acc, it) => acc + lineTotal(it), 0);
  return mode === 'half-even' ? applyBankersRounding(sum) : sum;
}

